async () => {
const t=[...document.querySelectorAll('body *')].filter(e=>e.children.length<6&&(e.textContent||'').includes('First box is in')&&e.offsetParent!==null).sort((a,b)=>a.textContent.length-b.textContent.length)[0]; if(!t) return 'none'; t.click(); return 'tapped';

}

